package com.google.javascript.rhino.jstype;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class PrototypeObjectType_matchConstraint_TriageGen2Test {

    @Mock
    private PrototypeObjectType prototypeObjectType;

    @Mock
    private JSType mockConstraint;

    @Mock
    private ObjectType mockObjectType;

    @Before
    public void setUp() {
        // Default behavior for mockConstraint to prevent NPE if needed, 
        // though logic usually depends on specific return values.
    }

    /**
     * Tests the first branch: if (hasReferenceName()) { return; }
     * This ensures that if the type is not anonymous, no further processing occurs.
     */
    @Test
    public void testMatchConstraint_WithReferenceName_ReturnsEarly() {
        // Arrange
        when(prototypeObjectType.hasReferenceName()).thenReturn(true);

        // Act
        prototypeObjectType.matchConstraint(mockConstraint);

        // Assert
        verify(prototypeObjectType, times(1)).hasReferenceName();
        // Verify that no other methods are called on prototypeObjectType or mockConstraint
        verify(mockConstraint, never()).isRecordType();
        verify(prototypeObjectType, never()).matchRecordTypeConstraint(any());
    }

    /**
     * Tests the second branch: if (constraint.isRecordType()) { matchRecordTypeConstraint(...) }
     * This ensures that for anonymous types, if the constraint is a record, 
     * the record matching logic is triggered.
     */
    @Test
    public void testMatchConstraint_WithRecordTypeConstraint_CallsMatchRecordTypeConstraint() {
        // Arrange
        when(prototypeObjectType.hasReferenceName()).thenReturn(false);
        when(mockConstraint.isRecordType()).thenReturn(true);
        when(mockConstraint.toObjectType()).thenReturn(mockObjectType);

        // Act
        prototypeObjectType.matchConstraint(mockConstraint);

        // Assert
        verify(prototypeObjectType).hasReferenceName();
        verify(mockConstraint).isRecordType();
        verify(mockConstraint).toObjectType();
        verify(prototypeObjectType).matchRecordTypeConstraint(mockObjectType);
    }

    /**
     * Tests the case where the type is anonymous but the constraint is NOT a record type.
     * This ensures the method completes without calling matchRecordTypeConstraint.
     */
    @Test
    public void testMatchConstraint_WithNonRecordTypeConstraint_DoesNothing() {
        // Arrange
        when(prototypeObjectType.hasReferenceName()).thenReturn(false);
        when(mockConstraint.isRecordType()).thenReturn(false);

        // Act
        prototypeObjectType.matchConstraint(mockConstraint);

        // Assert
        verify(prototypeObjectType).hasReferenceName();
        verify(mockConstraint).isRecordType();
        verify(mockConstraint, never()).toObjectType();
        verify(prototypeObjectType, never()).matchRecordTypeConstraint(any());
    }
}
